import plugin from 'tailwindcss/plugin';
import { resolveProperty } from './resolve-property.js';
import { log } from './log.js';
import {
  parseValue,
  parseFontSizeValue,
  validateValues,
} from './parse-value.js';
import { clamp } from './clamp.js';

const defaultOptions = {
  minSize: '23.4375rem',
  maxSize: '90rem',
};

function getBreakpointValue(customValue, fallback, screens, containers) {
  if (!customValue) {
    return {
      ...parseValue(fallback),
      isContainer: false,
    };
  }

  const isContainer = customValue.startsWith('@');

  const cleanValue = isContainer ? customValue.slice(1) : customValue;
  const value = isContainer
    ? containers[cleanValue] || cleanValue
    : screens[cleanValue] || cleanValue;

  return {
    ...parseValue(value),
    isContainer,
  };
}

const isLengthValue = (v) =>
  /^-?\d*\.?\d+(px|rem|em)$/.test(v.trim()) || v.trim() === '0';

export default plugin.withOptions(function (options = {}) {
  const o = { ...defaultOptions, ...options };
  return function ({ matchUtilities, addBase, theme, config }) {
    const clampTheme = theme('clamp') || {};

    // Separate theme values into variable definitions vs utility shortcuts
    const utilityValues = {};
    const variableDefinitions = {};

    for (const [name, value] of Object.entries(clampTheme)) {
      if (typeof value !== 'string') continue;
      const firstArg = value.split(',')[0];
      if (isLengthValue(firstArg)) {
        variableDefinitions[name] = value;
      } else {
        utilityValues[name] = value;
      }
    }

    // Process variable definitions → inject as computed CSS custom properties
    if (Object.keys(variableDefinitions).length > 0) {
      const screens = theme('screens');
      const containers = theme('containers');
      const rootVars = {};

      for (const [name, value] of Object.entries(variableDefinitions)) {
        const args = value.split(',').map((s) => s.trim());

        if (args.length < 2) {
          log.error(
            `Theme clamp variable "--clamp-${name}" requires at least 2 values (start, end).`,
          );
          continue;
        }

        const start = parseValue(args[0]);
        const end = parseValue(args[1]);

        const minvw = getBreakpointValue(
          args[2],
          o.minSize,
          screens,
          containers,
        );
        const maxvw = getBreakpointValue(
          args[3],
          o.maxSize,
          screens,
          containers,
        );

        if (!validateValues(minvw, maxvw, `--clamp-${name}`)) continue;
        if (!validateValues(start, end, `--clamp-${name}`)) continue;

        const useContainer = minvw.isContainer;
        rootVars[`--clamp-${name}`] = clamp(
          start,
          end,
          minvw,
          maxvw,
          useContainer,
        );
      }

      if (Object.keys(rootVars).length > 0) {
        addBase({ ':root': rootVars });
      }
    }

    matchUtilities(
      {
        clamp: (value) => {
          const args = value.split(',');

          if (args.length < 3) {
            log.error(
              `The clamp utility requires at least 3 arguments: "clamp-[${value}]".`,
            );
            return {};
          }

          const screens = theme('screens');
          const containers = theme('containers');

          const minvw = getBreakpointValue(
            args[3],
            o.minSize,
            screens,
            containers,
          );

          const maxvw = getBreakpointValue(
            args[4],
            o.maxSize,
            screens,
            containers,
          );

          if (!validateValues(minvw, maxvw, value)) {
            return {};
          }

          const useContainer = minvw.isContainer;
          const isCustomProperty = args[0].startsWith('--');
          const resolvedProp = isCustomProperty
            ? { type: 'regular', key: null, props: [args[0]] }
            : resolveProperty(args[0]);

          if (!resolvedProp) {
            log.error(
              `Property "${args[0]}" is not supported: "clamp-[${value}]".`,
            );
            return {};
          }

          const { key, props, type } = resolvedProp;

          // handle fontSize separately
          if (type === 'fontSize') {
            const start = parseFontSizeValue(
              config().theme[key][args[1]] || args[1],
            );
            const end = parseFontSizeValue(
              config().theme[key][args[2]] || args[2],
            );

            const css = {};

            Object.keys(start).forEach((k) => {
              if (k in end) {
                if (
                  (k === 'letterSpacing' || k === 'lineHeight') &&
                  start[k].number === end[k].number &&
                  start[k].unit === end[k].unit
                ) {
                  css[k] = `${start[k].number}${start[k].unit}`;
                } else if (validateValues(start[k], end[k], value, k)) {
                  const val = clamp(
                    start[k],
                    end[k],
                    minvw,
                    maxvw,
                    useContainer,
                  );
                  css[k] = val;
                }
              }
            });

            return css;
          }

          // Other values
          let start = parseValue(
            key ? config().theme[key]?.[args[1]] || args[1] : args[1],
          );
          let end = parseValue(
            key ? config().theme[key]?.[args[2]] || args[2] : args[2],
          );

          // Handle spacing values
          if (type === 'spacing') {
            const spacing = parseValue(
              typeof theme('spacing') === 'string'
                ? theme('spacing')
                : theme('spacing.1'),
            );

            const startIsUnitless = /^-?\d*\.?\d+$/.test(args[1]);
            const endIsUnitless = /^-?\d*\.?\d+$/.test(args[2]);

            if (startIsUnitless) {
              start = {
                number: spacing.number * parseFloat(args[1]),
                unit: spacing.unit,
              };
            }

            if (endIsUnitless) {
              end = {
                number: spacing.number * parseFloat(args[2]),
                unit: spacing.unit,
              };
            }
          }

          if (!validateValues(start, end, value)) {
            return {};
          }

          const val = clamp(start, end, minvw, maxvw, useContainer);

          const declarations = props.reduce((acc, prop) => {
            if (typeof prop === 'string') {
              acc[prop] = val;
            } else {
              acc = { ...acc, ...prop };
            }
            return acc;
          }, {});

          if (resolvedProp.selector) {
            return { [resolvedProp.selector]: declarations };
          }

          return declarations;
        },
      },
      { values: utilityValues },
      {
        supportsNegativeValues: false,
        modifiers: {
          pattern: /[\w-]+(?:,[\w-]+){2}/, // Matches "text,lg,3xl" format
        },
      },
    );
  };
});
